      "confidence": "high",
      "obligations": [
        {
          "kind": "attendance",
          "party": "Redhill District Council",
          "ask": "Attend the tribunal hearing",
          "deadline": "on 14 September 2026",
          "anchor": "14 September 2026"
        }
      ]
    },
    {
      "id": 903,
      "segment": "Please send us a reading from your meter at your earliest convenience.",
